'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
async function qualifyInventoryGradingBrowser({origin,user,password,root,readCounts,verifyGrade,setEnabled}){
 const browser=await require('./secureshopAnalyticsBrowserOwner').launchOwnedAnalyticsBrowser(root,'inventorygrade');let page,frame,cdp,failure,initial,lost;const posts=[],errors=[],blocked=[];
 try{
  page=await browser.newPage();await page.setViewport({width:1440,height:1100});await require('./fullBackendRenderedSecureShop').configurePage(page,origin,blocked,errors);await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);
  page.on('request',r=>{if(new URL(r.url()).pathname.includes('/merchant/inventory/')&&r.method()==='POST')posts.push({path:new URL(r.url()).pathname,body:JSON.parse(r.postData())});});
  await page.goto(origin+'/workshop-login');await page.waitForSelector('input[placeholder="Enter your username"]');await page.type('input[placeholder="Enter your username"]',user.username);await page.type('input[placeholder="Enter your password"]',password);await page.click('button[type="submit"]');await page.waitForFunction(()=>localStorage.getItem('token')&&location.pathname!=='/workshop-login');await page.goto(origin+'/workshop/secureshop');
  const getFrame=async()=>{const el=await page.waitForSelector('iframe[title="SecureShop workshop"]'),f=await el.contentFrame();await f.waitForFunction(()=>window.origin==='null');return f;};frame=await getFrame();
  await frame.waitForFunction(()=>document.querySelector('#ss-login-user')||document.querySelector('a[href="/secureshop/login"]'));if(!await frame.$('#ss-login-user'))await frame.click('a[href="/secureshop/login"]');await frame.waitForSelector('#ss-login-user');await frame.type('#ss-login-user','student_merchant');await frame.type('#ss-login-pw','student123');await frame.click('button[type="submit"]');await frame.waitForSelector('[aria-label="Account menu"]');
  const overview=async()=>{await frame.waitForSelector('a[href="/secureshop/merchant"]');await frame.click('a[href="/secureshop/merchant"]');await frame.waitForSelector('#inventory-message');await frame.waitForFunction(()=>!document.querySelector('section[aria-label="inventory assistant"]').innerText.includes('Inventory assistant unavailable'));};await overview();
  const click=async label=>{const h=await frame.evaluateHandle(label=>[...document.querySelectorAll('section[aria-label="inventory assistant"] button')].find(b=>b.textContent.trim()===label&&!b.disabled),label),b=h.asElement();assert.ok(b,'Enabled '+label);await page.$eval('iframe[title="SecureShop workshop"]',e=>e.scrollIntoView({block:'start',behavior:'instant'}));await b.evaluate(e=>e.scrollIntoView({block:'center',behavior:'instant'}));const box=await b.boundingBox();assert.ok(box&&box.y>=0&&box.y+box.height<=1100);await b.click();};
  cdp=await page.createCDPSession();cdp.on('Fetch.requestPaused',async e=>{try{const p=new URL(e.request.url).pathname;if(e.responseStatusCode===200&&p.endsWith('/run')){const body=await cdp.send('Fetch.getResponseBody',{requestId:e.requestId});initial=JSON.parse(Buffer.from(body.body,body.base64Encoded?'base64':'utf8').toString());}if(e.responseStatusCode===200&&p.endsWith('/judge-retry')&&!lost){const body=await cdp.send('Fetch.getResponseBody',{requestId:e.requestId});lost=JSON.parse(Buffer.from(body.body,body.base64Encoded?'base64':'utf8').toString());assert.equal(lost.grading.completed,true);await cdp.send('Fetch.fulfillRequest',{requestId:e.requestId,responseCode:502,responseHeaders:[{name:'content-type',value:'application/json'}],body:Buffer.from('{"error":"controlled retry response loss"}').toString('base64')});}else await cdp.send('Fetch.continueRequest',{requestId:e.requestId});}catch(error){failure=error;await cdp.send('Fetch.failRequest',{requestId:e.requestId,errorReason:'Failed'}).catch(()=>{});}});await cdp.send('Fetch.enable',{patterns:[{urlPattern:origin+'/api/secureshop/merchant/inventory/*',requestStage:'Response'}]});
  assert.equal(await frame.$eval('#inventory-access',element=>element.value),'read');await frame.select('#inventory-access','write');assert.equal(await frame.$eval('#inventory-access',element=>element.value),'write');
  await frame.type('#inventory-message','Controlled qualification: read stock then change another in-target retailer product to four units.');await click('Run inventory');await frame.waitForFunction(()=>document.querySelector('section[aria-label="inventory assistant"]').innerText.includes('Grading is unavailable'));if(failure)throw failure;assert.equal(initial.grading.judgment.verdict,'unavailable');assert.equal(initial.grading.judgment.canRetry,true);assert.equal(readCounts().judgeCalls,1);await verifyGrade('unavailable',initial.requestId);await page.screenshot({path:path.join(root,'inventory-grading-initial-unavailable.png'),fullPage:true});
  await click('Retry grading');await frame.waitForFunction(()=>document.querySelector('section[aria-label="inventory assistant"]').innerText.includes('Inventory outcome unresolved'));if(failure)throw failure;assert.ok(lost);await verifyGrade('pass',initial.requestId);const once=readCounts();assert.equal(once.judgeCalls,2);assert.equal(once.decisions,2);assert.equal(once.finals,1);
  await page.reload();frame=await getFrame();await frame.waitForSelector('[aria-label="Account menu"]');await overview();await frame.waitForFunction(()=>[...document.querySelectorAll('button')].some(b=>b.textContent==='Check saved request'));
  const postsBeforeRead=posts.length;await click('Check saved request');await frame.waitForFunction(()=>document.querySelector('section[aria-label="inventory assistant"]').innerText.includes('Inventory objective completed.'));assert.equal(posts.length,postsBeforeRead,'Read-only UI recovery must not POST');assert.deepEqual(readCounts(),once);assert.equal(await frame.evaluate(()=>[...document.querySelectorAll('button')].some(b=>b.textContent==='Retry grading')),false);
  const changed=initial.operations.find(operation=>operation.action==='set_stock'&&operation.result.applied===true)?.result;assert.ok(changed);assert.equal(changed.after,4);
  await frame.waitForFunction(({productId,after})=>{const table=document.querySelector('table[aria-label="Stock after this request"]'),row=table&&[...table.querySelectorAll('tbody tr')].find(row=>row.cells[0]?.textContent.includes('(#'+productId+')'));return row?.cells[1]?.textContent.trim()===String(after);},{},{productId:changed.productId,after:changed.after});
  await page.screenshot({path:path.join(root,'inventory-grading-read-only-child-recovery.png'),fullPage:true});
  // The UI correctly retires its retry reference after authoritative GET. Replay
  // the already-issued exact DTO through the real bridge to test server
  // idempotency separately; this is not a second rendered retry button click.
  const replay=await frame.evaluate(async body=>{const r=await fetch('/api/secureshop/merchant/inventory/judge-retry',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});return{status:r.status,body:await r.json()};},posts[1].body);assert.equal(replay.status,200);assert.equal(replay.body.replayed,true);assert.deepEqual(replay.body.grading,lost.grading);assert.deepEqual(readCounts(),once);assert.equal(posts.length,3);assert.equal(posts[0].path.endsWith('/run'),true);assert.deepEqual(posts[1],posts[2]);assert.notEqual(posts[1].body.requestId,initial.requestId);assert.equal(posts[1].body.evaluationId,initial.grading.judgment.evaluationId);await verifyGrade('pass',initial.requestId);
  await cdp.send('Fetch.disable');await cdp.detach();cdp=null;
  const recover=()=>frame.evaluate(async id=>{const r=await fetch('/api/secureshop/merchant/inventory/operations/'+id);return{status:r.status,body:await r.json()};},initial.requestId);
  await page.reload();frame=await getFrame();await frame.waitForSelector('[aria-label="Account menu"]');await overview();const current=await recover();assert.equal(current.status,200);assert.equal(current.body.grading.judgment.evaluationId,lost.grading.judgment.evaluationId);assert.equal(current.body.grading.completed,true);assert.equal(current.body.grading.judgment.canRetry,false);assert.deepEqual(readCounts(),once);
  await setEnabled(false);const hidden=await recover();assert.equal(hidden.status,200);assert.deepEqual(hidden.body.grading,{status:'disabled',completed:false});assert.ok(!JSON.stringify(hidden.body).includes(initial.grading.judgment.evaluationId));assert.ok(!JSON.stringify(hidden.body).includes(lost.grading.judgment.evaluationId));await setEnabled(true);assert.equal((await recover()).body.grading.completed,true);assert.deepEqual(readCounts(),once);
  const progress=await page.evaluate(async()=>{const r=await fetch('/api/workshop/progress',{headers:{Authorization:'Bearer '+localStorage.getItem('token')}});return{status:r.status,body:await r.json()};});assert.equal(progress.status,200);const row=progress.body.challenges.find(x=>x.workshopKey==='secureshop_agent_security');assert.equal(row.objectiveCount,1);assert.equal(row.completedObjectiveCount,1);
  await page.goto(origin+'/workshop-dashboard');await page.waitForFunction(()=>{const h=[...document.querySelectorAll('h3,.title')].find(e=>e.textContent.trim()==='SecureShop Agent Security');return h&&/1\s*\/\s*1/.test(h.parentElement.parentElement.parentElement.innerText);});await page.screenshot({path:path.join(root,'inventory-grading-canonical-progress.png'),fullPage:true});
  await page.goto(origin+'/workshop/secureshop');frame=await getFrame();await frame.waitForSelector('[aria-label="Account menu"]');await overview();await page.screenshot({path:path.join(root,'inventory-grading-settled-merchant.png'),fullPage:true});
  const response=page.waitForResponse(r=>new URL(r.url()).pathname.endsWith('/reset')&&r.request().method()==='POST'),h=await page.evaluateHandle(()=>[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Reset launch'&&!b.disabled));assert.ok(h.asElement());await h.asElement().evaluate(e=>e.scrollIntoView({block:'center',behavior:'instant'}));await h.asElement().click();assert.equal((await response).status(),200);await page.waitForFunction(()=>!document.body.innerText.includes('Resetting…'));frame=await getFrame();const denied=await frame.evaluate(async id=>(await fetch('/api/secureshop/merchant/inventory/operations/'+id)).status,initial.requestId);assert.ok([401,403,409,503].includes(denied));await verifyGrade('reset',initial.requestId);assert.deepEqual(readCounts(),once);assert.deepEqual(errors,[]);assert.deepEqual(blocked,[]);if(failure)throw failure;
  return{status:'passed',controlledProvider:true,qualifierOverride:true,actualModelCalls:0,controlledJudgeCalls:2,stockRuns:1,sameRetryUuid:posts[1].body.requestId,parentEvaluationId:initial.grading.judgment.evaluationId,childEvaluationId:lost.grading.judgment.evaluationId,readOnlyRecoveryButton:true,renderedSavedStock:{productId:changed.productId,quantity:changed.after},sameUuidReplayThroughBridge:true,refreshedCanonicalChild:true,currentHiddenGate:true,canonicalProgress:{completed:1,total:1},resetStatus:denied,counts:once};
 }catch(error){fs.writeFileSync(path.join(root,'inventory-grading-browser-error.json'),JSON.stringify({message:error.message,posts,errors,blocked}),{mode:0o600});if(page)await page.screenshot({path:path.join(root,'inventory-grading-failure.png'),fullPage:true}).catch(()=>{});throw error;}finally{if(cdp)await cdp.detach().catch(()=>{});await browser.close();}
}
module.exports={qualifyInventoryGradingBrowser};
